import React from 'react';
import { Star, BeerBottles, Beer, Camera, FaceHappy, FaceNeutral } from '@hexa-ui/icons';
import { ComponentMeta, ComponentStory } from '@storybook/react';
import { Badge } from '../..';

const BADGE_COLORS = ['black', 'green', 'error', 'orange', 'purple', 'yellow'] as const;

export default {
  title: 'Feedback/Badge/Category',
  component: Badge.Category,
  argTypes: {
    label: {
      description: 'Assing a text label to the badge',
      defaultValue: 'Label',
    },
    color: {
      description: 'Define one of the pre-defined color to badge background',
      defaultValue: 'black',
    },
    type: {
      description: 'Specify how the badge component should behave',
      defaultValue: 'default',
    },
    disabled: {
      description: 'Boolean value defining if is disabled or not',
      defaultValue: 'false',
    },
    icon: {
      description: 'A react node component that renders a icon',
      control: {
        type: null,
      },
    },
  },
  parameters: {
    docs: {
      description: {
        component:
          'How to install: `yarn add @hexa-ui/components`<br><br>How to import: `import { Badge } from "@hexa-ui/components"`<br><br> How to use: `Badge.Category` or destructure it `{ Category } = Badge`',
      },
    },
  },
} as ComponentMeta<typeof Badge.Category>;

const Template: ComponentStory<typeof Badge.Category> = (args) => <Badge.Category {...args} />;

export const Default = Template.bind({});

export const WithDefaultColors = (): JSX.Element => (
  <div style={{ display: 'flex' }}>
    {BADGE_COLORS.map((color) => (
      <div key={color} style={{ margin: '0.25rem' }}>
        <Badge.Category color={color} label={color} icon={Star} />
      </div>
    ))}
  </div>
);

export const WithInteractiveColors = (): JSX.Element => (
  <div style={{ display: 'flex' }}>
    {BADGE_COLORS.map((color) => (
      <div key={color} style={{ margin: '0.25rem' }}>
        <Badge.Category
          onClick={() => console.log('Clicked on color', color)}
          type="interactive"
          color={color}
          label="Interactive"
          icon={Star}
        />
      </div>
    ))}
  </div>
);

export const WithDisabled = (): JSX.Element => (
  <Badge.Category label="Disabled" disabled color="orange" />
);

export const WithCustomIcons = (): JSX.Element => (
  <div style={{ display: 'flex', gap: '0.5rem' }}>
    <Badge.Category icon={Star} label="Star" color="black" />
    <Badge.Category icon={BeerBottles} label="Beer bottles" color="green" />
    <Badge.Category icon={Camera} label="Camera" color="error" />
    <Badge.Category icon={Beer} label="Beer" color="orange" />
    <Badge.Category icon={FaceHappy} label="Face happy" color="purple" />
    <Badge.Category icon={FaceNeutral} label="Face neutral" color="yellow" />
  </div>
);
